package vmcompat;
import java.nio.*;import java.util.*;import org.lwjgl.opengl.*;import org.lwjgl.system.MemoryUtil;
/** ShellArena-only CPU packets. No GPU readback or duplicate geometry. */
public final class FarShell {
 static final long OWNER_LIMIT=32L<<20,AUX_LIMIT=8L<<20;static final int RANGE_CHARGE=128,ROW_CHARGE=256,PAGE_METADATA=16384,BASE_METADATA=32768;
 static final Map<ContextResources.Group,Budget> BUDGETS=Collections.synchronizedMap(new WeakHashMap<>());
 static final Map<Long,State> LIVE=new java.util.concurrent.ConcurrentHashMap<>();
 static final class Budget {long owner,aux;final List<Pending> pending=new ArrayList<>();}
 record Pending(int buffer,int texture,long owner,long aux){}
 record Range(int first,int count,int id){}
 static final class Page {int slot,buffer,originalVao,owner,vao,vertices,nextId;long generation,storage,bytes;final TreeMap<Integer,Range> ranges=new TreeMap<>();}
 static final class Span {Page page;int start,count,lookupBase;IntBuffer first,counts;final Map<Integer,Integer> draws=new HashMap<>();}
 static boolean base(Budget b){synchronized(b){if(b.aux+BASE_METADATA>AUX_LIMIT)return false;b.aux+=BASE_METADATA;return true;}}
 static final class State {final ContextResources.Identity identity=ContextResources.current();final Budget budget=BUDGETS.computeIfAbsent(identity.group(),k->new Budget());final boolean accounted=base(budget);final Map<Integer,Page> pages=new HashMap<>();int maxTexels=GL11.glGetInteger(GL31.GL_MAX_TEXTURE_BUFFER_SIZE);Span[] spans;long commandsAt,temporary;int program,modeLoc,baseLoc,recordBuffer,recordTexture,packetCapacity;FloatBuffer packet;IntBuffer labels;boolean active;}
 static final StateStore<State> LOCAL=new StateStore<>(()->{State s=new State();LIVE.put(s.identity.handle(),s);return s;});
 static State state(){State s=LOCAL.get();if(!s.budget.pending.isEmpty()){for(Pending p:s.budget.pending){if(p.texture!=0)Textures.glDeleteTextures(p.texture);if(p.buffer!=0)Buffers.glDeleteBuffers(p.buffer);s.budget.owner-=p.owner;s.budget.aux-=p.aux;}s.budget.pending.clear();}return s;}
 static boolean trusted(State s){return s.accounted&&ContextResources.opaqueExclusive()&&s.identity.group().trusted&&s.identity.group().contexts==1;}
 static boolean reserve(State s,long owner,long aux){return owner>=0&&aux>=0&&s.budget.owner+owner<=OWNER_LIMIT&&s.budget.aux+aux<=AUX_LIMIT;}
 static void gauge(State s){FarStats.memory(s.budget.owner,s.budget.aux);}
 public static void page(int slot,int buffer,int vao){if(!Options.FAR_BATCH)return;State s=state();Page old=s.pages.remove(slot);if(old!=null){release(s,old,true);s.budget.aux-=PAGE_METADATA;}if(!s.accounted||s.pages.size()>=256||!reserve(s,0,PAGE_METADATA)){FarStats.add(FarStats.K.REJECTED_PAGES,1);return;}s.budget.aux+=PAGE_METADATA;Page p=new Page();p.slot=slot;p.buffer=buffer;p.originalVao=vao;long[] id=Buffers.identity(buffer);p.generation=id[0];p.storage=id[1];p.vertices=(int)Math.min(Integer.MAX_VALUE,id[3]/40);s.pages.put(slot,p);}
 public static void remove(int slot){if(!Options.FAR_BATCH)return;State s=state();Page p=s.pages.remove(slot);if(p!=null){release(s,p,true);s.budget.aux-=PAGE_METADATA;}}
 public static void bufferDeleted(int buffer){if(!Options.FAR_BATCH)return;State s=state();for(var it=s.pages.entrySet().iterator();it.hasNext();){Page p=it.next().getValue();if(p.buffer==buffer){it.remove();release(s,p,true);s.budget.aux-=PAGE_METADATA;}}}
 public static void free(int first,int count,int pageVertices){if(!Options.FAR_BATCH||pageVertices<=0||first<0||count<=0)return;State s=state();Page p=s.pages.get(first/pageVertices);if(p!=null)invalidate(s,p,first%pageVertices,count);}
 static void invalidate(State s,Page p,int first,int count){int removed=0;for(var it=p.ranges.entrySet().iterator();it.hasNext();){Range r=it.next().getValue();if((long)r.first+r.count>first&&(long)first+count>r.first){it.remove();removed++;}}s.budget.aux-=(long)removed*RANGE_CHARGE;gauge(s);}
 public static void uploadGeometry(int target,long offset,ByteBuffer data){Buffers.glBufferSubData(target,offset,data);if(!Options.FAR_BATCH)return;State s=state();int buffer=GL11.glGetInteger(GL15.GL_ARRAY_BUFFER_BINDING);for(Page p:s.pages.values())if(p.buffer==buffer)invalidate(s,p,(int)(offset/40),(data.remaining()+39)/40);}
 static void release(State s,Page p,boolean current){if(p.vao!=0&&current)Draws.glDeleteVertexArrays(p.vao);if(p.owner!=0){if(current){Buffers.glDeleteBuffers(p.owner);s.budget.owner-=p.bytes;}else s.budget.pending.add(new Pending(p.owner,0,p.bytes,0));}s.budget.aux-=(long)p.ranges.size()*RANGE_CHARGE;p.ranges.clear();p.owner=p.vao=p.nextId=0;p.bytes=0;gauge(s);}
 public static void closeWindow(long window){State s=LIVE.remove(window);if(s==null)return;boolean current=org.lwjgl.glfw.GLFW.glfwGetCurrentContext()==window;for(Page p:s.pages.values())release(s,p,current);s.budget.aux-=(long)s.pages.size()*PAGE_METADATA;s.pages.clear();if(s.accounted)s.budget.aux-=BASE_METADATA;clearPlan(s);if(s.packet!=null){MemoryUtil.memFree(s.packet);s.budget.aux-=(long)s.packetCapacity*4;}if(s.labels!=null){MemoryUtil.memFree(s.labels);s.budget.aux-=16384;}if(s.recordTexture!=0&&current)Textures.glDeleteTextures(s.recordTexture);if(s.recordBuffer!=0){long bytes=(long)s.packetCapacity*4;if(current){Buffers.glDeleteBuffers(s.recordBuffer);s.budget.aux-=bytes;}else s.budget.pending.add(new Pending(s.recordBuffer,s.recordTexture,0,bytes));}gauge(s);}
 static void clearPlan(State s){if(s.spans!=null)for(Span p:s.spans)if(p!=null){if(p.first!=null)MemoryUtil.memFree(p.first);if(p.counts!=null)MemoryUtil.memFree(p.counts);}s.spans=null;s.budget.aux-=s.temporary;s.temporary=0;s.active=false;}
 static String validate(State s,Page p){if(p==null)return "missing_page";long[] id=Buffers.identity(p.buffer);if(id[0]!=p.generation||id[1]!=p.storage){release(s,p,true);p.generation=id[0];p.storage=id[1];p.vertices=(int)Math.min(Integer.MAX_VALUE,id[3]/40);}if(p.vertices<=0||id[3]%40!=0)return "storage_layout";if(!Draws.farLayout(p.originalVao,p.buffer))return "vertex_layout";return null;}
 /** Typed issue bridge receives the ORIGINAL CPU fields, not mirrored GL buffers. */
 public static void begin(FloatBuffer records,int recordCount,IntBuffer commands,IntBuffer instances,int[] spans,int spanInts,long commandsAt){if(!Options.FAR_BATCH)return;long started=System.nanoTime();State s=state();clearPlan(s);s.commandsAt=commandsAt;
  try{
   if(!trusted(s)){FarStats.issueFallback("context",spanInts);return;}int program=GL11.glGetInteger(GL20.GL_CURRENT_PROGRAM);if(!FarShaders.qualified(program)){FarStats.issueFallback("shader",spanInts);return;}
   if(records==null||commands==null||instances==null||spans==null||spanInts<0||spanInts>spans.length||spanInts%5!=0||recordCount<0||(long)recordCount*8>records.limit()){FarStats.issueFallback("cpu_packet",spanInts);return;}
   s.program=program;var qualified=FarShaders.qualification(program);s.modeLoc=qualified.mode();s.baseLoc=qualified.base();if(s.modeLoc<0||s.baseLoc<0){FarStats.issueFallback("uniforms",spanInts);return;}
   int spanCount=spanInts/5;boolean candidate=false;for(int i=0;i<spanCount;i++)if(spans[i*5+4]>=2){candidate=true;break;}if(!candidate){FarStats.fallback("small_span",spanCount);return;}if(!reserve(s,0,(long)spanCount*128)){FarStats.issueFallback("aux_budget",spanInts);return;}s.spans=new Span[spanCount];s.temporary=(long)spanCount*128;s.budget.aux+=s.temporary;
   long texels=(long)recordCount*2;int supported=0;
   for(int i=0;i<spanCount;i++){
    int at=i*5,pageSlot=spans[at],start=spans[at+3],count=spans[at+4],atlases=spans[at+2];Page page=s.pages.get(pageSlot);String reason=validate(s,page);if(reason==null&&(count<2||start<0||((long)start+count)*4>commands.limit()||atlases<1||atlases>4))reason="span_bounds_or_small";
    long charge=(long)Math.max(0,count)*ROW_CHARGE;if(reason==null&&!reserve(s,0,charge))reason="aux_budget";
    Span plan=null;var pending=new TreeMap<Integer,Range>();int next=page==null?0:page.nextId;
    if(reason==null){plan=new Span();plan.page=page;plan.start=start;plan.count=count;
     for(int j=0;j<count;j++){int row=(start+j)*4,n=commands.get(row),inst=commands.get(row+1),first=commands.get(row+2),base=commands.get(row+3);if(n==0){if(first<0){reason="command";break;}continue;}if(inst!=1||n<0||first<0||n%3!=0||(long)first+n>page.vertices||base<0||base>=instances.limit()){reason="command";break;}int packed=instances.get(base),record=packed&0xffffff,atlas=packed>>>24;if(record>=recordCount||atlas>=atlases){reason="record_or_atlas";break;}
      Range range=page.ranges.get(first);if(range!=null&&range.count!=n){reason="overlap";break;}if(range==null)range=pending.get(first);if(range!=null&&range.count!=n){reason="overlap";break;}
      if(range==null){var a=page.ranges.floorEntry(first);var b=page.ranges.ceilingEntry(first);var c=pending.floorEntry(first);var d=pending.ceilingEntry(first);if((a!=null&&(long)a.getValue().first+a.getValue().count>first)||(b!=null&&b.getKey()<(long)first+n)||(c!=null&&(long)c.getValue().first+c.getValue().count>first)||(d!=null&&d.getKey()<(long)first+n)){reason="overlap";break;}range=new Range(first,n,next++);pending.put(first,range);}Integer prior=plan.draws.putIfAbsent(range.id,packed);if(prior!=null&&prior!=packed){reason="conflicting_draw";break;}
     }
    }
    if(reason==null&&plan.draws.isEmpty())reason="empty";
    long ownerNeed=page!=null&&page.owner==0?(long)page.vertices*4:0,registry=(long)pending.size()*RANGE_CHARGE;
    long lookup=reason==null?(long)next:0;long capacity=(texels+lookup)*4;long packetNeed=capacity>s.packetCapacity?capacity*8-(long)s.packetCapacity*8:0;
    if(reason==null&&(!reserve(s,ownerNeed,charge+registry+packetNeed+(s.labels==null?16384:0))||next<0||capacity>Integer.MAX_VALUE||texels+lookup>s.maxTexels))reason="memory_budget";
    if(reason!=null){FarStats.fallback(reason);continue;}
    FarStats.add(FarStats.K.ELIGIBLE,1);s.budget.aux+=charge;s.temporary+=charge;
    ensurePage(s,page);for(Range r:pending.values()){writeOwner(s,page,r);page.ranges.put(r.first,r);s.budget.aux+=RANGE_CHARGE;FarStats.add(FarStats.K.OWNER_NEW,1);}page.nextId=next;FarStats.add(FarStats.K.OWNER_HITS,Math.max(0,plan.draws.size()-pending.size()));plan.lookupBase=(int)texels;texels+=(long)page.nextId; // texels, not floats
    plan.first=MemoryUtil.memAllocInt(count);plan.counts=MemoryUtil.memAllocInt(count);for(int j=0;j<count;j++){plan.first.put(j,commands.get((start+j)*4+2));plan.counts.put(j,commands.get((start+j)*4));}s.spans[i]=plan;supported++;
   }
   if(supported==0)return;
   int floats=Math.toIntExact(texels*4);if((long)floats*8+s.budget.aux-(long)s.packetCapacity*8>AUX_LIMIT){clearPlan(s);FarStats.fallback("packet_budget",supported);return;}ensurePacket(s,floats);s.packet.clear().limit(floats);FloatBuffer original=records.duplicate();original.position(0).limit(recordCount*8);s.packet.put(original);while(s.packet.position()<floats)s.packet.put(0);for(Span p:s.spans)if(p!=null)for(var entry:p.draws.entrySet()){int ix=(p.lookupBase+entry.getKey())*4,packed=entry.getValue();s.packet.put(ix,(float)(packed&0xffffff)).put(ix+1,(float)(packed>>>24));}s.packet.position(0).limit(floats);
   long upload=System.nanoTime();int old=GL11.glGetInteger(GL15.GL_ARRAY_BUFFER_BINDING);try{GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,s.recordBuffer);Buffers.glBufferSubData(GL15.GL_ARRAY_BUFFER,0,s.packet);}finally{GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,old);}FarStats.add(FarStats.K.UPLOAD_NS,System.nanoTime()-upload);FarStats.add(FarStats.K.LOOKUP_BYTES,(texels-recordCount*2L)*16);s.active=true;
  }finally{gauge(s);FarStats.add(FarStats.K.PREPARE_NS,System.nanoTime()-started);}
 }
 static void ensurePacket(State s,int floats){if(s.packetCapacity>=floats)return;int old=GL11.glGetInteger(GL15.GL_ARRAY_BUFFER_BINDING),active=Samplers.activeUnit();long delta=(long)(floats-s.packetCapacity)*8;FloatBuffer next=MemoryUtil.memAllocFloat(floats);if(s.packet!=null)MemoryUtil.memFree(s.packet);s.packet=next;s.packetCapacity=floats;s.budget.aux+=delta;
  try{if(s.recordBuffer==0){s.recordBuffer=Buffers.glGenBuffers();Buffers.auxiliary(s.recordBuffer);}GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,s.recordBuffer);Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,(long)floats*4,GL15.GL_STREAM_DRAW);if(s.recordTexture==0)s.recordTexture=Textures.glCreateTextures(GL31.GL_TEXTURE_BUFFER);int unit=active,texture=Samplers.boundTexture(unit,GL31.GL_TEXTURE_BUFFER);try{Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,s.recordTexture);Buffers.glTexBuffer(GL31.GL_TEXTURE_BUFFER,GL30.GL_RGBA32F,s.recordBuffer);}finally{Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,texture);}}finally{GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,old);Samplers.glActiveTexture(GL13.GL_TEXTURE0+active);}}
 static void ensurePage(State s,Page p){if(p.owner!=0)return;int saved=GL11.glGetInteger(GL15.GL_ARRAY_BUFFER_BINDING),vao=Draws.vertexArrayBinding();try{p.owner=Buffers.glGenBuffers();Buffers.auxiliary(p.owner);GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,p.owner);p.bytes=(long)p.vertices*4;Buffers.glBufferData(GL15.GL_ARRAY_BUFFER,p.bytes,GL15.GL_STATIC_DRAW);s.budget.owner+=p.bytes;p.vao=GL30.glGenVertexArrays();Draws.glBindVertexArray(p.vao);GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,p.buffer);int[] size={3,2,4,3,1,1},type={GL11.GL_FLOAT,GL11.GL_FLOAT,GL11.GL_UNSIGNED_SHORT,GL11.GL_BYTE,GL11.GL_FLOAT,GL11.GL_INT},off={0,12,20,28,32,36};for(int i=0;i<6;i++){if(i==5)Draws.glVertexAttribIPointer(i,size[i],type[i],40,off[i]);else Draws.glVertexAttribPointer(i,size[i],type[i],i==2||i==3,40,off[i]);Draws.glEnableVertexAttribArray(i);Draws.glVertexAttribDivisor(i,0);}GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,p.owner);Draws.glVertexAttribIPointer(6,1,GL11.GL_INT,4,0);Draws.glEnableVertexAttribArray(6);Draws.glVertexAttribDivisor(6,0);}finally{Draws.glBindVertexArray(vao);GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,saved);}}
 static void writeOwner(State s,Page p,Range r){if(s.labels==null){s.labels=MemoryUtil.memAllocInt(4096);s.budget.aux+=16384;}int saved=GL11.glGetInteger(GL15.GL_ARRAY_BUFFER_BINDING);try{GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,p.owner);for(int offset=0;offset<r.count;){int n=Math.min(4096,r.count-offset);s.labels.clear().limit(n);for(int i=0;i<n;i++)s.labels.put(i,r.id);Buffers.glBufferSubData(GL15.GL_ARRAY_BUFFER,(long)(r.first+offset)*4,s.labels);offset+=n;}}finally{GL15.glBindBuffer(GL15.GL_ARRAY_BUFFER,saved);}}
 /** Called at the original span callsite, after original atlas/floor bindings. */
 public static void draw(int mode,long offset,int count,int stride,int spanIndex,int originalTexture){FarStats.add(FarStats.K.COMMANDS,Math.max(0,count));State s=Options.FAR_BATCH?state():null;Span p=s!=null&&s.active&&s.spans!=null&&spanIndex>=0&&spanIndex<s.spans.length?s.spans[spanIndex]:null;
  if(p==null||mode!=GL11.GL_TRIANGLES||stride!=16||p.count!=count||offset!=s.commandsAt+(long)p.start*16){if(p!=null)FarStats.fallback("draw_boundary");Draws.glMultiDrawArraysIndirect(mode,offset,count,stride);return;}
  int savedVao=Draws.vertexArrayBinding(),active=Samplers.activeUnit(),location=FarShaders.qualification(s.program).sampler();int unit=Samplers.logicalUnit(s.program,location);int texture=Samplers.boundTexture(unit,GL31.GL_TEXTURE_BUFFER);long started=System.nanoTime();
  try{Samplers.glActiveTexture(GL13.GL_TEXTURE0+unit);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,s.recordTexture);Draws.glBindVertexArray(p.page.vao);GL20.glUniform1i(s.modeLoc,1);GL20.glUniform1i(s.baseLoc,p.lookupBase);Draws.farArrays(mode,p.first,p.counts);FarStats.add(FarStats.K.BATCHED,1);FarStats.add(FarStats.K.NATIVE_BATCHES,1);long vertices=0;for(int i=0;i<count;i++)vertices+=p.counts.get(i);FarStats.add(FarStats.K.VERTICES,vertices);
  }finally{GL20.glUniform1i(s.modeLoc,0);GL20.glUniform1i(s.baseLoc,0);Draws.glBindVertexArray(savedVao);Samplers.glActiveTexture(GL13.GL_TEXTURE0+unit);Samplers.glBindTexture(GL31.GL_TEXTURE_BUFFER,texture);Samplers.restoreInput(s.program,location,texture);Samplers.glActiveTexture(GL13.GL_TEXTURE0+active);FarStats.add(FarStats.K.SUBMIT_NS,System.nanoTime()-started);}
 }
 public static void end(){if(!Options.FAR_BATCH)return;State s=state();clearPlan(s);gauge(s);}
}
